namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
template<class T,class A>void shortBudgets(T&task,const kstation::FlashCredits&credits,unsigned&calls,uint64_t&checks,A&&advance){auto cost=task.nextClocks(credits);std::array<uint8_t,sizeof(T)>snapshot;std::memcpy(snapshot.data(),&task,sizeof(T));auto before=calls;for(unsigned budget=0;budget<cost;++budget){check(!advance(budget)&&calls==before&&!std::memcmp(snapshot.data(),&task,sizeof(T)),"Short budget mutated task/IO");++checks;}}
class Original final:public H8SEmulator{public:int readHistory()const{return lastread;}int writeHistory()const{return lastwrite;}int irqDepth()const{return indent;}void histories(int r,int w){lastread=r;lastwrite=w;}void irqDepth(int d){indent=d;}};
using C=kstation::Stage1Cpu;
struct Event{uint64_t clocks;unsigned pc,at;std::array<int32_t,8>regs;uint8_t flags,exr,value;bool write;};
template<class Cpu>class Bus final:public H8SDevice{public:Cpu&c;unsigned count=0,command=0,remaining=0,pageWrites=0,lcdReads=0,lcdBusy=0,lastReads=0,stallReads=0;bool dropLast=false;unsigned dropIndex=~0u;uint32_t page=0,tick=0;std::array<Event,8>events{};explicit Bus(Cpu&p):c(p){}void record(unsigned at,uint8_t v,bool w){check(count<events.size(),"IO overflow");auto&e=events[count++];e={c.cycles,unsigned(c.getPC()),at,{},c.ccr,c.exr,v,w};for(unsigned j=0;j<8;++j)e.regs[j]=c.regs[j].er;}uint8_t read(unsigned at)override{uint8_t v=c.memory[at];if(at>=0xfffd20&&at<=0xfffd23){if(at==0xfffd20)tick=uint32_t(c.cycles/1000);v=uint8_t(tick>>((0xfffd23-at)*8));}if(at==0xffffc7)v=lcdReads++<lcdBusy?0x80:0;if(pageWrites==256&&at==page+255&&lastReads++<stallReads)v^=1;record(at,v,false);return v;}
 void write(unsigned at,uint8_t v)override{record(at,v,true);if(at>=0x200000&&at<0x240000){auto offset=at-0x200000;if(command==3){if(!pageWrites)page=at;if((!dropLast||remaining!=1)&&pageWrites!=dropIndex)c.memory[at]=v;++pageWrites;if(!--remaining)command=0;return;}if(command==0&&offset==0x5555&&v==0xaa)command=1;else if(command==1&&offset==0x2aaa&&v==0x55)command=2;else if(command==2&&offset==0x5555&&v==0xa0){command=3;remaining=256;}else command=0;return;}c.memory[at]=v;}
};
struct Fixture {std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<C>b=std::make_unique<C>();Bus<Original>x{*a};Bus<C>y{*b};kstation::NativeFlashState native;uint64_t handlers=0,steps=0,io=0,programs=0,irqSteps=0,mutations=0;bool nested=false,mutate=false,injected=false;void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=b->memory[at&0xffffff]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){word(at,v>>16);word(at+2,v);}
 explicit Fixture(const std::vector<uint8_t>&rom){a->loadmem(rom.data(),rom.size(),0);b->loadmem(rom.data(),rom.size(),0);for(auto r:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xbb00,0x200},std::pair{0xce00,0x200},std::pair{0x3fff80,0x100}}){a->memmap(&x,r.first,r.second);b->memmap(&y,r.first,r.second);}}
 void prepare(unsigned entry,unsigned flags,unsigned target=0x21fe00,unsigned sp=0xffff00){native.reset();for(unsigned j=0;j<8;++j)a->regs[j].er=b->regs[j].er=int32_t(0x9a6c0011+j*0x122334);a->pc=a->makepc(entry);b->pc=b->makepc(entry);a->setSP(sp);b->setSP(sp);wide(sp,0x3ae8);a->reg32(5)=b->reg32(5)=0xce1e;a->reg32(6)=b->reg32(6)=target;a->cycles=b->cycles=flags==255?~uint64_t(0)-5:100000;a->ccr=b->ccr=uint8_t(flags);a->exr=b->exr=0x5a;a->pending_irqs=b->pending_irqs=0;a->histories(0x200001,0xfffe6f);b->histories(0x200001,0xfffe6f);a->irqDepth(3);b->irqDepth(3);x.command=y.command=x.remaining=y.remaining=x.pageWrites=y.pageWrites=x.lcdReads=y.lcdReads=x.lcdBusy=y.lcdBusy=x.lastReads=y.lastReads=x.stallReads=y.stallReads=0;x.dropLast=y.dropLast=false;x.dropIndex=y.dropIndex=~0u;nested=mutate=injected=false;word(0xfffe32,0xfffe);for(unsigned j=0;j<256;++j){byte(0xce1e + j,j*73+19);byte(0x21fe00+j,j*73+19);byte(0x21ff00+j,j*13+7);}for(unsigned j=0;j<23;++j)byte(0xbb12+j,j*17+3);++handlers;}
 void equal(unsigned at){bool same=a->cycles==b->cycles&&a->getPC()==b->getPC()&&a->ccr==b->ccr&&a->exr==b->exr&&a->readHistory()==b->readHistory()&&a->writeHistory()==b->writeHistory()&&a->irqDepth()==b->irqDepth();for(unsigned j=0;j<8;++j)same&=a->regs[j].er==b->regs[j].er;if(!same){std::fprintf(stderr,"At%x PC%x/%x clocks%llu/%llu flags%x/%x R0%x/%x R1%x/%x R2%x/%x R5%x/%x R6%x/%x\n",at,a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->reg32(0),b->reg32(0),a->reg32(1),b->reg32(1),a->reg32(2),b->reg32(2),a->reg32(5),b->reg32(5),a->reg32(6),b->reg32(6));throw std::runtime_error("Context differs");}check(x.count==y.count,"IO count differs");for(unsigned j=0;j<x.count;++j){auto&p=x.events[j];auto&q=y.events[j];if(!(p.clocks==q.clocks&&p.pc==q.pc&&p.at==q.at&&p.regs==q.regs&&p.flags==q.flags&&p.exr==q.exr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"IO At%x event%u at%x/%x value%x/%x flags%x/%x clocks%llu/%llu\n",at,j,p.at,q.at,p.value,q.value,p.flags,q.flags,p.clocks,q.clocks);throw std::runtime_error("IO context differs");}}io+=x.count;}
 void whole(){for(unsigned j=0;j<250000&&a->getPC()!=0x3ae8;++j){x.count=y.count=0;auto at=unsigned(a->getPC());if(!injected&&at==0xc40&&unsigned(a->reg32(0))%256==128&&(nested||mutate)){if(nested)a->pending_irqs=b->pending_irqs=uint64_t(1)<<38;if(mutate){byte(0xce1e + 128,0x17);++mutations;}injected=true;}try{if((a->pending_irqs&&!(a->ccr&128))||(at>=0x92c&&at<0x946)){check(kstation::NativeIrq::step(*b).stepped,"Timer3 native refused");++irqSteps;}else check(native.step(*b),"Native step refused");}catch(...){a->step();std::fprintf(stderr,"Failed at%x clocks%llu/%llu next%x/%x\n",at,a->cycles,b->cycles,a->getPC(),b->getPC());throw;}a->step();equal(at);++steps;}check(a->getPC()==0x3ae8&&!native.active(),"Graph incomplete");for(auto r:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xbb00,0x200},std::pair{0xce00,0x200},std::pair{0x3fff80,0x100}})check(!std::memcmp(a->memory+r.first,b->memory+r.first,r.second),"RAM/Flash/canary differs");check(x.pageWrites==y.pageWrites,"Program count differs");programs+=x.pageWrites==256;}
};}
int main(int argc,char**argv){try{if(argc<2){std::puts("SKIP private K ROM required");return 77;}std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");Fixture f(rom);for(unsigned flags=0;flags<256;++flags){f.prepare(0xc82,flags);f.whole();f.prepare(0xbc0,flags);f.byte(0x21fe00,0xff);f.whole();}for(unsigned i=0;i<256;++i){f.prepare(0xc82,0xff);f.byte(0x21fe00+i,0xff^(i*73+19));f.whole();}
 for(unsigned target:{0x1fffffu,0x200000u,0x20ff00u,0x21fe01u,0xa021fe00u}){f.prepare(0xbc0,0xff,target);f.whole();}for(unsigned entry:{0x4d96u,0x55a4u,0x5556u,0x20e2u,0x2306u,0x22fcu,0x229eu,0x2284u})for(unsigned sp:{0xffff00u,0x3fffffu,0x400001u}){f.prepare(entry,0xff,0x21fe00,sp);f.x.lcdBusy=f.y.lcdBusy=3;f.whole();}
 f.prepare(0xbc0,0xff);f.byte(0x21fe00,0xff);f.byte(0x21feff,0xee);f.x.dropLast=f.y.dropLast=true;f.whole();check(uint32_t(f.a->reg32(6))&0x80000000u,"Busy timeout branch not reached");f.prepare(0xbc0,0xff);f.byte(0x21fe00,0xff);f.x.stallReads=f.y.stallReads=5;f.whole();check(f.x.lastReads>=6,"Busy loop not reached");f.prepare(0xbc0,0x80);f.byte(0x21fe80,0xee);f.x.dropIndex=f.y.dropIndex=128;f.whole();check(uint32_t(f.a->reg32(6))&0x80000000u,"Postverify failure branch not reached");f.prepare(0xbc0,0);f.byte(0x21fe00,0xff);f.nested=f.mutate=true;f.whole();check(f.injected&&f.irqSteps>0,"Nested interrupt not reached");
 check(f.a->memory[0xce1e + 128]==0x17&&f.a->memory[0x21fe80]==0x93,"Read/write phase was not live/retained");
 uint64_t shorts=0,blocked=0;unsigned calls=0;kstation::FlashCredits cr;
 using CT=kstation::FlashCompareTask;for(unsigned mismatch:{0u,255u,256u}){CT task{0,0};while(!task.complete()){auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&](CT::Read field,unsigned index){++calls;return unsigned(uint8_t(index*73+19)^(field==CT::Read::Target&&index==mismatch?1:0));});};shortBudgets(task,cr,calls,shorts,advance);check(advance(task.nextClocks(cr))>0,"Compare progress");}}
 using PT=kstation::FlashPageTask;for(unsigned policy=0;policy<7;++policy){PT task{0,policy==0?0x1fffffu:policy==1?0x200000u:policy==2?0x21fe01u:0x21fe00u};unsigned comparisons=0;while(!task.complete()){if(task.awaitingCompare()){for(unsigned i=0;i<8;++i){auto before=task.stage();check(!task.nextClocks(cr)&&!task.advanceBefore(10000,cr,[&](auto,auto)->unsigned{throw std::runtime_error("Blocked compare read");},[&](auto,auto,auto){throw std::runtime_error("Blocked compare write");})&&task.stage()==before,"Blocked compare advanced");++blocked;}check(task.resumeCompare(policy==3||comparisons++>0),"Compare resume");continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&](PT::Read field,unsigned index){++calls;return field==PT::Read::Dirty?0xffffu:field==PT::Read::Source?unsigned(uint8_t(index*73+19)):field==PT::Read::TickStart?100u:field==PT::Read::Tick?policy==5?115u:100u:unsigned(uint8_t(255*73+19));},[&](auto,auto,auto){++calls;});};shortBudgets(task,cr,calls,shorts,advance);check(advance(task.nextClocks(cr))>0,"Page progress");}}
 using GT=kstation::GlobalStateTask;for(auto kind:{GT::Kind::Load,GT::Kind::Backup}){GT task{kind};while(!task.complete()){auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&](unsigned index){++calls;return index*73+19;},[&](unsigned index,unsigned value){++calls;check(value==unsigned(uint8_t(index*73+19))||kind==GT::Kind::Backup&&index>=23&&value==0,"Global copy/zero value");});};shortBudgets(task,cr,calls,shorts,advance);check(advance(task.nextClocks(cr))>0,"Global progress");}}
 using BT=kstation::FlashBackupTask;for(unsigned dirty:{0u,1u}){BT task;while(!task.complete()){if(task.awaiting()){check(!task.nextClocks(cr)&&!task.advanceBefore(10000,cr,[&]()->unsigned{throw std::runtime_error("Blocked backup read");},[&](auto){throw std::runtime_error("Blocked backup write");}),"Backup child advanced");++blocked;task.resume();continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&]{++calls;return dirty;},[&](auto){++calls;});};shortBudgets(task,cr,calls,shorts,advance);check(advance(task.nextClocks(cr))>0,"Backup progress");}}
 using LT=kstation::LcdTask;for(auto kind:{LT::Kind::Read,LT::Kind::Write,LT::Kind::Ready,LT::Kind::Command,LT::Kind::Notify}){LT task{kind,0x9a};unsigned children=0;while(!task.complete()){if(task.awaiting()){check(!task.nextClocks(cr)&&!task.advanceBefore(10000,cr,[&]()->unsigned{throw std::runtime_error("Blocked LCD read");},[&](auto,auto){throw std::runtime_error("Blocked LCD write");}),"LCD child advanced");++blocked;task.resumeChild(children++<3?0x80:0);continue;}auto advance=[&](unsigned budget){return task.advanceBefore(budget,cr,[&]{++calls;return 0xa4;},[&](auto,auto){++calls;});};shortBudgets(task,cr,calls,shorts,advance);check(advance(task.nextClocks(cr))>0,"LCD progress");}if(kind==LT::Kind::Read)check(task.value()==0xa4,"LCD read result was overwritten");}
 std::printf("{\"passed\":true,\"handlers\":%llu,\"native_phases\":%llu,\"ordered_context_io\":%llu,\"page_programs\":%llu,\"original_child_steps\":0,\"nested_native_irq_phases\":%llu,\"live_source_mutations\":%llu,\"pure_short_budgets\":%llu,\"blocked_child_guards\":%llu}\n",f.handlers,f.steps,f.io,f.programs,f.irqSteps,f.mutations,shorts,blocked);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
